# --- cenario do exercicio: nao precisa mudar nada aqui ---
class HTTPException(Exception):
    def __init__(self, status_code, detail=""):
        self.status_code = status_code
        self.detail = detail
        super().__init__(detail)


class Ticket:
    def __init__(self, id, usuario_id, titulo):
        self.id = id
        self.usuario_id = usuario_id
        self.titulo = titulo


class Usuario:
    def __init__(self, id):
        self.id = id


class Repositorio:
    def __init__(self, tickets):
        self._tickets = {t.id: t for t in tickets}

    def buscar(self, ticket_id):
        return self._tickets.get(ticket_id)


repo = Repositorio([Ticket(1, "ana", "impressora sem toner"), Ticket(2, "bruno", "vpn caiu")])
ana = Usuario("ana")
bruno = Usuario("bruno")


def status_ao_chamar(ticket_id, usuario):
    """Status da HTTPException levantada, ou None se nao levantou."""
    try:
        obter_ticket(ticket_id, usuario)
        return None
    except HTTPException as erro:
        return erro.status_code


# --- daqui para baixo e com voce ---
def obter_ticket(ticket_id, usuario):
    ticket = repo.buscar(ticket_id)

    # Mesma resposta para "não existe" e "não é seu": 403 revelaria a existência.
    if ticket is None or ticket.usuario_id != usuario.id:
        raise HTTPException(status_code=404, detail="ticket não encontrado")

    return ticket

