sem_papel = {"id": "ana"}


# O papel vem do usuário da sessão; nada aqui aceita parâmetro do cliente.
def tickets_visiveis(usuario, tickets):
    if usuario.get("papel") == "suporte":
        return list(tickets)

    # Padrão restrito: qualquer papel que não seja suporte vê só o que é seu.
    return [t for t in tickets if t.get("usuario_id") == usuario.get("id")]
